import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { User, Edit, LogOut, Award, Mail, BookOpen } from "lucide-react";
import "../App.css"; 

const Profile = () => {
  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState(false);

  // 1. LOAD DATA FROM MEMORY (So it doesn't revert to "Srija")
  const [userData, setUserData] = useState({
    name: localStorage.getItem("userName") || "Student",
    email: localStorage.getItem("userEmail") || "No Email",
    grade: "Grade 10",
    xp: 1402
  });

  // 2. THE SAVE FUNCTION
  const handleSave = () => {
    // A. Save the new name to the browser's memory
    localStorage.setItem("userName", userData.name);
    localStorage.setItem("userEmail", userData.email);

    // B. Turn off edit mode
    setIsEditing(false);

    // C. THE MAGIC FIX: Reload the page automatically!
    // This forces the Navbar to wake up and see the new name.
    window.location.reload(); 
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  return (
    <div className="profile-container">
       <div className="profile-header-card">
          <div className="profile-avatar">
             <User size={40} color="#10b981" />
          </div>

          <div className="profile-info">
             {isEditing ? (
               /* EDIT MODE */
               <div className="edit-form">
                  <input 
                    type="text" 
                    value={userData.name}
                    onChange={(e) => setUserData({...userData, name: e.target.value})}
                    className="input-field"
                  />
                  <input 
                    type="text" 
                    value={userData.email}
                    onChange={(e) => setUserData({...userData, email: e.target.value})}
                    className="input-field"
                  />
                  <button className="btn-save" onClick={handleSave}>Save</button>
               </div>
             ) : (
               /* VIEW MODE */
               <>
                 <h2 className="profile-name">{userData.name}</h2>
                 <p className="profile-details">{userData.grade} • {userData.email}</p>
               </>
             )}
          </div>

          <div className="profile-actions">
             {!isEditing && (
                <button className="btn-edit" onClick={() => setIsEditing(true)}>
                   <Edit size={16} /> Edit Profile
                </button>
             )}
             <button className="btn-logout" onClick={handleLogout}>
                <LogOut size={16} /> Sign Out
             </button>
          </div>
       </div>

       {/* Stats Section */}
       <div className="stats-grid">
          <div className="stat-card">
             <div className="stat-icon bg-green"><Award size={24} color="white"/></div>
             <div>
                <h3>{userData.xp} XP</h3>
                <p>Total Points</p>
             </div>
          </div>
          <div className="stat-card">
             <div className="stat-icon bg-blue"><BookOpen size={24} color="white"/></div>
             <div>
                <h3>12</h3>
                <p>Lessons Completed</p>
             </div>
          </div>
       </div>
    </div>
  );
};

export default Profile;
